import{_ as s,o as e,c as i,a2 as n}from"./chunks/framework.BI_TNnOW.js";const u=JSON.parse('{"title":"Introducción a los scripts","description":"","frontmatter":{},"headers":[],"relativePath":"es/content/000-intro.md","filePath":"es/content/000-intro.md"}'),o={name:"es/content/000-intro.md"};function t(l,a,r,p,c,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="introduccion-a-los-scripts" tabindex="-1">Introducción a los scripts <a class="header-anchor" href="#introduccion-a-los-scripts" aria-label="Permalink to &quot;Introducción a los scripts&quot;">​</a></h1><p>Bash (Bourne Again SHell) es uno de los intérpretes de comandos más populares en el ecosistema de Linux y sistemas similares a Unix. Un script de Bash no es más que un archivo de texto plano que contiene instrucciones escritas en el lenguaje de comandos de Bash, el cual se encarga de ejecutar línea a línea todo lo que allí se indique. Estos scripts resultan especialmente útiles para automatizar tareas, ya sea en el entorno de un solo usuario o a nivel de sistema.</p><p>La gran ventaja de crear scripts en Bash radica en su simplicidad y en la compatibilidad que ofrece, pues casi todas las distribuciones de Linux lo incluyen por defecto. Además, no se necesitan herramientas de compilación ni dependencias complicadas: basta con un editor de texto y el intérprete de Bash. Con estos dos elementos, se pueden desarrollar desde simples automatizaciones, como la limpieza de archivos temporales, hasta complejos sistemas de despliegue y administración de servidores.</p><p>A lo largo de este tema, aprenderás a crear y gestionar scripts de Bash, así como buenas prácticas para su uso. Conocerás también los permisos de ejecución, la manera de invocar scripts directamente desde la línea de comandos y las formas de aprovechar al máximo las numerosas utilidades que ofrece el propio shell (tuberías, redirecciones, variables, funciones, entre otros). De esta manera, estarás preparado para llevar a cabo todo tipo de automatizaciones y procesos repetitivos de forma rápida y segura.</p><h2 id="hola-mundo" tabindex="-1">Hola mundo <a class="header-anchor" href="#hola-mundo" aria-label="Permalink to &quot;Hola mundo&quot;">​</a></h2><p>A continuación, se muestra un ejemplo sencillo de un script de Bash que imprime &quot;Hola Mundo&quot;, junto con los pasos necesarios para ejecutarlo.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hola Mundo&quot;</span></span></code></pre></div><h3 id="pasos-para-ejecutarlo" tabindex="-1">Pasos para ejecutarlo <a class="header-anchor" href="#pasos-para-ejecutarlo" aria-label="Permalink to &quot;Pasos para ejecutarlo&quot;">​</a></h3><ol><li><p><strong>Crear el archivo</strong> Crea un archivo (por ejemplo, <code>hola.sh</code>) y pega en él el código anterior.</p></li><li><p><strong>Dar permisos de ejecución</strong> Desde la terminal, navega hasta la ubicación del archivo y ejecuta:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hola.sh</span></span></code></pre></div></li><li><p><strong>Ejecutar el script</strong> Una vez que le hayas otorgado los permisos de ejecución, puedes ejecutar tu script con:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./hola.sh</span></span></code></pre></div></li></ol><p>Al ejecutarlo, verás el mensaje:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hola Mundo</span></span></code></pre></div><h2 id="shebang" tabindex="-1">Shebang <a class="header-anchor" href="#shebang" aria-label="Permalink to &quot;Shebang&quot;">​</a></h2><p>El <strong>shebang</strong> (o <code>#!</code>) es una secuencia de caracteres que aparece al inicio de un script y le indica al sistema operativo qué intérprete debe usarse para ejecutar el archivo. En el caso de scripts de Bash, el shebang típico es:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span></code></pre></div><p>Se compone de:</p><ol><li><code>#!</code>: Este símbolo indica al sistema que lo que sigue es la ruta del intérprete.</li><li><code>/bin/bash</code>: Es la ruta al intérprete de Bash en el sistema. Indica que las instrucciones del script deben ejecutarse usando Bash.</li></ol><p>Si el shebang está correctamente configurado, el sistema sabrá qué intérprete utilizar para procesar el script.</p><h2 id="comentarios-en-bash" tabindex="-1">Comentarios en Bash <a class="header-anchor" href="#comentarios-en-bash" aria-label="Permalink to &quot;Comentarios en Bash&quot;">​</a></h2><p>En Bash, los comentarios se utilizan para explicar partes del código, agregar notas o documentar el propósito y funcionamiento de un script. Los comentarios no se ejecutan y son ignorados por el intérprete.</p><h3 id="sintaxis-basica" tabindex="-1">Sintaxis básica <a class="header-anchor" href="#sintaxis-basica" aria-label="Permalink to &quot;Sintaxis básica&quot;">​</a></h3><p>Los comentarios en Bash comienzan con el símbolo <code>#</code>. Todo lo que aparezca después de este símbolo en la misma línea será considerado un comentario.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Este es un comentario</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hola Mundo&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Este comentario explica este comando</span></span></code></pre></div><h3 id="comentarios-multilinea" tabindex="-1">Comentarios multilínea <a class="header-anchor" href="#comentarios-multilinea" aria-label="Permalink to &quot;Comentarios multilínea&quot;">​</a></h3><p>Bash no tiene una sintaxis específica para comentarios multilínea, pero puedes usar varios <code>#</code> consecutivos:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Este es un comentario</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># que abarca</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># varias líneas</span></span></code></pre></div><h3 id="buenas-practicas-con-comentarios" tabindex="-1">Buenas prácticas con comentarios <a class="header-anchor" href="#buenas-practicas-con-comentarios" aria-label="Permalink to &quot;Buenas prácticas con comentarios&quot;">​</a></h3><ol><li><strong>Claros y relevantes</strong>: Los comentarios deben explicar el propósito del código y no repetir obviedades. <ul><li>Mal comentario:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Imprime Hola Mundo</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hola Mundo&quot;</span></span></code></pre></div></li><li>Buen comentario:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Mensaje de bienvenida al usuario</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hola Mundo&quot;</span></span></code></pre></div></li></ul></li><li><strong>Mantenerlos actualizados</strong>: Siempre que se modifique el código, los comentarios deben reflejar los cambios.</li><li><strong>No abusar</strong>: Demasiados comentarios pueden dificultar la lectura. El código debe ser lo suficientemente claro como para no requerir comentarios extensos.</li><li><strong>Usar comentarios para deshabilitar código temporalmente</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># echo &quot;Esto no se ejecutará&quot;</span></span></code></pre></div></li></ol><p>Los comentarios son una herramienta poderosa para documentar scripts y garantizar su mantenimiento y comprensión a largo plazo.</p><h2 id="variables-en-bash" tabindex="-1">Variables en Bash <a class="header-anchor" href="#variables-en-bash" aria-label="Permalink to &quot;Variables en Bash&quot;">​</a></h2><p>En Bash, las variables se utilizan para almacenar valores que pueden ser reutilizados en el script. Estas variables no tienen un tipo específico y pueden contener texto, números o incluso resultados de comandos.</p><h3 id="declaracion-de-variables" tabindex="-1">Declaración de variables <a class="header-anchor" href="#declaracion-de-variables" aria-label="Permalink to &quot;Declaración de variables&quot;">​</a></h3><p>En Bash, las variables se asignan simplemente usando el signo igual <code>=</code> sin espacios antes ni después del signo.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Asignación de una variable</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mensaje</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hola Mundo&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Uso de la variable</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $mensaje</span></span></code></pre></div><p>En el ejemplo, el contenido de la variable <code>mensaje</code> se muestra utilizando el signo <code>$</code> seguido del nombre de la variable.</p><h3 id="reglas-para-nombres-de-variables" tabindex="-1">Reglas para nombres de variables <a class="header-anchor" href="#reglas-para-nombres-de-variables" aria-label="Permalink to &quot;Reglas para nombres de variables&quot;">​</a></h3><ol><li>Los nombres de las variables deben comenzar con una letra o un guion bajo <code>_</code>.</li><li>Solo pueden contener letras, números y guiones bajos (<code>_</code>).</li><li>No deben incluir espacios ni caracteres especiales.</li><li>Es preferible usar nombres significativos.</li></ol><h3 id="tipos-de-variables" tabindex="-1">Tipos de variables <a class="header-anchor" href="#tipos-de-variables" aria-label="Permalink to &quot;Tipos de variables&quot;">​</a></h3><ol><li><strong>Variables locales</strong>: Son aquellas declaradas dentro de un script o función y disponibles solo en ese contexto.<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nombre</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Juan&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $nombre</span></span></code></pre></div></li><li><strong>Variables de entorno</strong>: Son variables globales que afectan a procesos hijos. Se declaran usando el comando <code>export</code>.<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH:/nuevo/directorio</span></span></code></pre></div></li><li><strong>Variables especiales</strong>: Bash proporciona variables internas con significados específicos. Ejemplo: <ul><li><code>$0</code>: Nombre del script.</li><li><code>$1, $2, ...,$n</code>: Argumentos pasados al script.</li><li><code>$#</code>: Número de argumentos.</li><li><code>$?</code>: Código de salida del último comando ejecutado.</li></ul></li></ol><h3 id="operaciones-con-variables" tabindex="-1">Operaciones con variables <a class="header-anchor" href="#operaciones-con-variables" aria-label="Permalink to &quot;Operaciones con variables&quot;">​</a></h3><ol><li><strong>Concatenación</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">saludo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hola&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nombre</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Juan&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mensaje</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$saludo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $nombre</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $mensaje</span></span></code></pre></div></li><li><strong>Sustitución de comandos</strong>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">fecha</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hoy es: </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$fecha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div></li></ol>`,40)])])}const k=s(o,[["render",t]]);export{u as __pageData,k as default};
